class KeysIterator {
    constructor(map) {
        this.map = map;
        this.mapIterator = this.map.keys();
    }
    [Symbol.iterator]() {
        return new KeysIterator(this.map);
    }
    next() {
        while (true) {
            const result = this.mapIterator.next();
            if (result.done) {
                return { done: true, value: undefined };
            }
            const key = result.value;
            if (this.map.get(key).deref() !== undefined) {
                return { done: false, value: key };
            }
        }
    }
}

class ValuesIterator {
    constructor(mapIterator) {
        this.mapIterator = mapIterator;
    }
    [Symbol.iterator]() {
        return new ValuesIterator(this.mapIterator[Symbol.iterator]());
    }
    next() {
        while (true) {
            const result = this.mapIterator.next();
            if (result.done) {
                return { done: true, value: undefined };
            }
            const value = result.value.deref();
            if (value !== undefined) {
                return { done: false, value };
            }
        }
    }
}

class EntriesIterator {
    constructor(mapIterator) {
        this.mapIterator = mapIterator;
    }
    [Symbol.iterator]() {
        return new EntriesIterator(this.mapIterator[Symbol.iterator]());
    }
    next() {
        while (true) {
            const result = this.mapIterator.next();
            if (result.done) {
                return { done: true, value: undefined };
            }
            const [key, ref] = result.value;
            const value = ref.deref();
            if (value !== undefined) {
                return { done: false, value: [key, value] };
            }
        }
    }
}

class WeakValueMap {
    constructor(autoCleanup = true) {
        this.map = new Map();
        if (autoCleanup) {
            this.finalizer = new FinalizationRegistry((key) => {
                const ref = this.map.get(key);
                // Only delete if the ref is truly gone — guard against key reuse
                if (!ref || ref.deref() === undefined) {
                    this.map.delete(key);
                }
            });
        }
    }
    /**
     * Returns the number of entries in the map, including entries whose values
     * may have already been garbage-collected but not yet cleaned up.
     * Use `verify()` first if you need an accurate count of live entries.
     */
    get approximateSize() {
        return this.map.size;
    }
    keys() {
        return new KeysIterator(this.map);
    }
    values() {
        return new ValuesIterator(this.map.values());
    }
    entries() {
        return new EntriesIterator(this.map.entries());
    }
    set(key, value) {
        this.map.set(key, new WeakRef(value));
        if (this.finalizer) {
            this.finalizer.register(value, key);
        }
        return this;
    }
    get(key) {
        const ref = this.map.get(key);
        return ref && ref.deref();
    }
    has(key) {
        return this.get(key) !== undefined;
    }
    delete(key) {
        return this.map.delete(key);
    }
    clear() {
        this.map.clear();
    }
    forEach(callback) {
        this.map.forEach((ref, key) => {
            const value = ref.deref();
            // Only skip truly collected entries (deref returns undefined), not falsy values
            if (value !== undefined) {
                callback(value, key, this);
            }
        });
    }
    /**
     * Rebuilds the internal map retaining only entries whose values are still alive.
     * Useful when `autoCleanup` is disabled or when you need an accurate `approximateSize`.
     */
    verify() {
        const map = new Map();
        this.map.forEach((ref, key) => {
            if (ref.deref() !== undefined) {
                map.set(key, ref);
            }
        });
        this.map = map;
    }
}

class WeakStorage extends WeakValueMap {
    constructor(autoCleanup) {
        super(autoCleanup);
        this.byValues = new WeakMap();
    }
    set(key, value) {
        super.set(key, value);
        // Fix: store value→key (not key→value) so that getKey(value) works correctly
        this.byValues.set(value, key);
        return this;
    }
    /**
     * Returns the key associated with a given value, or `undefined` if not found.
     */
    getKey(value) {
        return this.byValues.get(value);
    }
    delete(key) {
        const value = this.get(key);
        if (value !== undefined) {
            this.byValues.delete(value);
        }
        return super.delete(key);
    }
    clear() {
        super.clear();
        this.byValues = new WeakMap();
    }
}

export { WeakStorage, WeakValueMap };
